"""Assemble the actual AXI frontend, packet CDC, startup and word backend."""
import hashlib
import json
from pathlib import Path
from generate_hyperram_cdc_timing_harness import ports


def module_header(name,public,parameters=True):
    result=['`timescale 1ns/1ps','`default_nettype none',
        '// Generated by tools/generate_async_hyperram_controller.py.',
        '// Word-level interface only; package DDR/RWDS capture is separate.']
    result +=[f'module {name} #(', '    parameter MEMORY_CLOCK_HZ=200000000,CONFIG_LATENCY=7,FIXED_LATENCY=1',')(']if parameters else[f'module {name}(']
    result +=[f'    {d} wire {w} {n}{","if i+1<len(public)else""}'for i,(d,w,n)in enumerate(public)]
    return result+[');']


def main():
    root=Path(__file__).resolve().parents[1];sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
    names=('axi_hyperram_bridge','hyperram_clock_bridge','hyperram_startup','hyperram_transaction_engine')
    paths={n:root/'rtl'/(n+'.v')for n in names}
    fp,cp,sp,ep=(ports(paths[n].read_text(),n)for n in names)
    status=('fabric_reset','phy_reset_n','memory_ready','startup_fault','startup_detail','startup_phase',
        'contents_lost','device_id0','device_id1','config_readback')
    public=[('input','','clk'),('input','','rst'),('input','','power_good'),('input','','phy_ready'),
        ('input','','contents_reload_ack'),('input','','external_transactions_idle')]
    public +=[(d,w,n)for d,w,n in sp if n in status]
    public +=[(d,w,n)for d,w,n in cp if n.startswith('s_cmd_')]
    public +=[('output','','s_rsp_valid'),('input','','s_rsp_ready'),('output','[511:0]','s_rsp_data'),
        ('output','','s_rsp_error'),('output','[7:0]','s_rsp_detail'),('output','','idle')]
    public +=[(d,w,n)for d,w,n in ep if n.startswith('phy_')]
    assert len({n for _,_,n in public})==len(public)
    lines=module_header('hyperram_word_backend',public)
    lines +=['wire engine_reset,engine_enable,engine_idle;','wire [3:0] engine_latency;',
        'wire engine_fixed_latency;',
        'assign idle=memory_ready&&engine_idle&&!s_cmd_valid&&!s_rsp_valid;']
    for _,w,n in sp:
        if n.startswith('init_'):lines.append(f'wire {w} {n};')
    for _,w,n in ep:
        if n.startswith(('cmd_','rsp_')):lines.append(f'wire {w} {n};')
    for n in('valid','write','address','data'):
        lines.append(f'assign cmd_{n}=memory_ready?s_cmd_{n}:init_cmd_{n};')
    lines +=["assign cmd_register=!memory_ready;","assign cmd_bytes=memory_ready?s_cmd_bytes:7'd2;",
        "assign cmd_strobes=memory_ready?s_cmd_strobes:64'd3;",'assign s_cmd_ready=memory_ready&&cmd_ready;',
        'assign init_cmd_ready=!memory_ready&&cmd_ready;','assign rsp_ready=memory_ready?s_rsp_ready:init_rsp_ready;']
    for n in('valid','data','error'):
        lines.append(f'assign s_rsp_{n}='+('memory_ready&&rsp_valid'if n=='valid'else'rsp_'+n)+';')
        lines.append(f'assign init_rsp_{n}='+('!memory_ready&&rsp_valid'if n=='valid'else'rsp_'+n)+';')
    lines +=['assign s_rsp_detail=rsp_detail;','assign init_rsp_detail=rsp_detail;',
        'hyperram_startup #(.MEMORY_CLOCK_HZ(MEMORY_CLOCK_HZ),.CONFIG_LATENCY(CONFIG_LATENCY),.FIXED_LATENCY(FIXED_LATENCY)) startup(',
        ',\n'.join(f'    .{n}('+('external_transactions_idle&&engine_idle&&!s_cmd_valid&&!s_rsp_valid'if n=='transactions_idle'else n)+')'for _,_,n in sp),');']
    remap={'rst':'engine_reset','enable':'engine_enable','cfg_latency':'engine_latency','cfg_fixed_latency':'engine_fixed_latency','idle':'engine_idle'}
    lines +=['hyperram_transaction_engine #(.MEMORY_CLOCK_HZ(MEMORY_CLOCK_HZ)) engine(',
        ',\n'.join(f'    .{n}({remap.get(n,n)})'for _,_,n in ep),');','endmodule','`default_nettype wire','']
    backend=root/'rtl/hyperram_word_backend.v';backend.write_text('\n'.join(lines))
    public=[('input','','app_clk'),('input','','mem_clk'),('input','','rst'),
        ('input','','power_good_mem'),('input','','phy_ready_mem'),
        ('output','','app_reset'),('output','','mem_reset')]
    public +=[(d,w.replace('ADDR_WIDTH','23'),n)for d,w,n in fp if n.startswith('s_axi_')]
    public +=[(d,w,n)for d,w,n in ep if n.startswith('phy_')]
    public +=[('input','','reload_ack_valid'),('output','','reload_ack_ready'),
        ('output','','reload_done_valid'),('input','','reload_done_ready'),
        ('output','','memory_ready_app'),('output','','startup_fault_app'),('output','','contents_lost_app'),
        ('output','[7:0]','memory_detail_app'),('output','','idle_app'),('output','[3:0]','fifo_errors')]
    public +=[(d,w,n+'_mem')for d,w,n in sp if n in status and n not in('fabric_reset','phy_reset_n')]
    public +=[('output','','phy_reset_n')]
    assert len({n for _,_,n in public})==len(public)
    lines=module_header('axi_hyperram_async_controller',public)
    lines +=['wire reset_request=rst||!power_good_mem||!phy_ready_mem;',
        'wire bridge_app_reset,bridge_mem_reset,req_app_reset,req_mem_reset,done_mem_reset,done_app_reset;',
        'assign app_reset=bridge_app_reset||req_app_reset||done_app_reset;',
        'assign mem_reset=bridge_mem_reset||req_mem_reset||done_mem_reset;',
        'wire frontend_idle,backend_idle,unused_fabric_reset;','wire contents_reload_ack_mem;',
        'wire request_ready_app,request_valid_mem,request_ready_mem,request_data_mem;',
        'wire done_ready_mem,done_valid_app,done_ready_app,done_data_app;',
        'wire [3:0] control_fifo_errors,bridge_fifo_errors;',
        'assign fifo_errors=control_fifo_errors|bridge_fifo_errors;','reg [1:0] reload_state;',
        'wire freeze_app=reload_state!=0||(reload_ack_valid&&reload_ack_ready);',
        'assign reload_ack_ready=!app_reset&&reload_state==0&&frontend_idle&&memory_ready_app&&!startup_fault_app;',
        'assign reload_done_valid=!app_reset&&reload_state==3&&!contents_lost_app;',
        'assign idle_app=!app_reset&&memory_ready_app&&frontend_idle&&reload_state==0;',
        'always @(posedge app_clk)begin',
        '    if(app_reset)reload_state<=0;',
        '    else case(reload_state)',
        '        0:if(reload_ack_valid&&reload_ack_ready)reload_state<=1;',
        '        1:if(request_ready_app)reload_state<=2;',
        '        2:if(done_valid_app)reload_state<=3;',
        '        3:if(reload_done_valid&&reload_done_ready)reload_state<=0;',
        '    endcase','end']
    for _,w,n in fp:
        if n.startswith('hb_'):lines.append(f'wire {w.replace("ADDR_WIDTH","23")} {n};')
    for _,w,n in cp:
        if n.startswith(('m_cmd_','m_rsp_')):lines.append(f'wire {w} {n};')
    for channel in('ar','aw','w'):
        lines +=[f'wire frontend_{channel}ready;',f'assign s_axi_{channel}ready=frontend_{channel}ready&&!freeze_app;']
    fmap={'clk':'app_clk','rst':'app_reset','idle':'frontend_idle'}
    for channel in('ar','aw','w'):
        fmap['s_axi_'+channel+'valid']='s_axi_'+channel+'valid&&!freeze_app'
        fmap['s_axi_'+channel+'ready']='frontend_'+channel+'ready'
    lines +=['axi_hyperram_bridge #(.ADDR_WIDTH(23)) frontend(',
        ',\n'.join(f'    .{n}({fmap.get(n,n)})'for _,_,n in fp),');','wire [7:0] returned_detail_app;']
    cmap={'app_reset':'bridge_app_reset','mem_reset':'bridge_mem_reset','s_rsp_detail':'returned_detail_app','fifo_errors':'bridge_fifo_errors'}
    for _,_,n in cp:
        if n.startswith('s_cmd_'):cmap[n]='hb_cmd_'+n[6:]
        elif n.startswith('s_rsp_')and n!='s_rsp_detail':cmap[n]='hb_rsp_'+n[6:]
    lines +=['hyperram_clock_bridge clock_bridge(',
        ',\n'.join(f'    .{n}({cmap.get(n,n)})'for _,_,n in cp),');',
        'assign done_ready_app=!app_reset&&reload_state==2;',
        'assign request_ready_mem=!mem_reset&&memory_ready_mem&&backend_idle&&!m_cmd_valid&&done_ready_mem;',
        'assign contents_reload_ack_mem=request_valid_mem&&request_ready_mem;',
        'cdc_packet_fifo #(.WIDTH(1)) reload_request(',
        '    .s_clk(app_clk),.m_clk(mem_clk),.reset_request(reset_request),.s_data(1\'b1),',
        '    .s_valid(!app_reset&&reload_state==1),.s_ready(request_ready_app),',
        '    .m_data(request_data_mem),.m_valid(request_valid_mem),.m_ready(request_ready_mem),',
        '    .s_reset(req_app_reset),.m_reset(req_mem_reset),.overflow(control_fifo_errors[0]),.underflow(control_fifo_errors[1]));',
        'cdc_packet_fifo #(.WIDTH(1)) reload_completion(',
        '    .s_clk(mem_clk),.m_clk(app_clk),.reset_request(reset_request),.s_data(1\'b1),',
        '    .s_valid(contents_reload_ack_mem),.s_ready(done_ready_mem),',
        '    .m_data(done_data_app),.m_valid(done_valid_app),.m_ready(done_ready_app),',
        '    .s_reset(done_mem_reset),.m_reset(done_app_reset),.overflow(control_fifo_errors[2]),.underflow(control_fifo_errors[3]));',
        '// The reload request is issued only after frontend drain, with admission frozen.',
        'hyperram_word_backend #(.MEMORY_CLOCK_HZ(MEMORY_CLOCK_HZ),.CONFIG_LATENCY(CONFIG_LATENCY),.FIXED_LATENCY(FIXED_LATENCY)) backend(']
    bp=ports(backend.read_text(),'hyperram_word_backend')
    bmap={'clk':'mem_clk','rst':'mem_reset','power_good':'power_good_mem','phy_ready':'phy_ready_mem',
        'contents_reload_ack':'contents_reload_ack_mem','external_transactions_idle':"1'b1",'fabric_reset':'unused_fabric_reset','idle':'backend_idle'}
    for n in status:
        if n not in('fabric_reset','phy_reset_n'):bmap[n]=n+'_mem'
    for _,_,n in bp:
        if n.startswith('s_cmd_'):bmap[n]='m_cmd_'+n[6:]
        elif n.startswith('s_rsp_'):bmap[n]='m_rsp_'+n[6:]
    lines +=[',\n'.join(f'    .{n}({bmap.get(n,n)})'for _,_,n in bp),');']
    for name in('memory_ready','startup_fault','contents_lost'):
        lines +=[f'wire {name}_sync;',
            f'xpm_cdc_single #(.DEST_SYNC_FF(3),.INIT_SYNC_FF(1),.SIM_ASSERT_CHK(1),.SRC_INPUT_REG(0)) {name}_synchronizer(',
            f'    .src_clk(mem_clk),.src_in({name}_mem),.dest_clk(app_clk),.dest_out({name}_sync));',
            f'assign {name}_app='+('app_reset||'if name=='contents_lost'else'!app_reset&&')+name+'_sync;']
    lines +=['reg [7:0] last_memory_detail;',
        'always @(posedge app_clk)begin',
        '    if(app_reset)last_memory_detail<=0;',
        '    else if(hb_rsp_valid&&hb_rsp_ready)last_memory_detail<=returned_detail_app;',
        'end','assign memory_detail_app=last_memory_detail;',
        'endmodule','`default_nettype wire','']
    target=root/'rtl/axi_hyperram_async_controller.v';target.write_text('\n'.join(lines))
    result=dict(generator_sha256=sha(Path(__file__)),port_parser_sha256=sha(root/'tools/generate_hyperram_cdc_timing_harness.py'),
        inputs_sha256={p.relative_to(root).as_posix():sha(p)for p in list(paths.values())+[root/'rtl/cdc_packet_fifo.v']},
        outputs_sha256={p.relative_to(root).as_posix():sha(p)for p in(backend,target)},
        frontend_and_clock_bridge_and_actual_word_backend_connected=True,
        complete_assembly_functionally_verified=False,native_timing_verified=False,pin_level_phy_present=False,
        tokenizer_instantiation_verified=False,full_system_complete=False)
    folder=root/'build/hyperram-async';folder.mkdir(parents=True,exist_ok=True)
    (folder/'generation.json').write_text(json.dumps(result,indent=2)+'\n');print(json.dumps(result))


if __name__=='__main__':main()
